(7666114, 1250287, 65234, '<td valign="top">LOL! Yeah, I don''t see trying to push him(her?) out of the way. Nice capture.</td>', 'LOL! Yeah, I don''t see trying to push him(her?) out of the way. Nice capture.', '2020-06-12 11:22:03.000000', NULL, 1),
(7666115, 1250547, 65234, '<td valign="top">Love those sheep, and the misty morning feel to this.</td>', 'Love those sheep, and the misty morning feel to this.', '2020-06-12 11:22:39.000000', NULL, 1),
(7666116, 1250650, 65234, '<td valign="top">Very pretty colors. Autumn bathed in golden light.</td>', 'Very pretty colors. Autumn bathed in golden light.', '2020-06-12 11:23:41.000000', NULL, 1),
(7666117, 1250686, 65234, '<td valign="top">Great path! I would absolutely love to follow it through those wetlands.</td>', 'Great path! I would absolutely love to follow it through those wetlands.', '2020-06-12 11:24:18.000000', NULL, 1),
(7666118, 1250660, 65234, '<td valign="top">I like the trees framing the road.</td>', 'I like the trees framing the road.', '2020-06-12 11:24:35.000000', NULL, 1),
(7666119, 1250684, 65234, '<td valign="top">Perfect timing on the capture. The cyclist makes it much more interesting.</td>', 'Perfect timing on the capture. The cyclist makes it much more interesting.', '2020-06-12 11:25:46.000000', NULL, 1),
(7666120, 1250472, 65234, '<td valign="top">Or the way up. Depends on where you look and where you''re going ;-) That trail looks terrifying, BTW. So many opportunities to fall.</td>', 'Or the way up. Depends on where you look and where you''re going ;-) That trail looks terrifying, BTW. So many opportunities to fall.', '2020-06-12 11:27:13.000000', NULL, 1),
(7666121, 1250506, 65234, '<td valign="top">Beautiful and mysterious path.</td>', 'Beautiful and mysterious path.', '2020-06-12 11:27:48.000000', NULL, 1),
(7666122, 1250640, 65234, '<td valign="top">Very cute! A natural model. I can''t get mine to sit still long enough for a picture! This pup looks ready to run down that trail as soon as you give the word.</td>', 'Very cute! A natural model. I can''t get mine to sit still long enough for a picture! This pup looks ready to run down that trail as soon as you give the word.', '2020-06-12 11:28:54.000000', NULL, 1),
(7666124, 1250608, 65234, '<td valign="top">Very nice timing on the capture. I like the darkness in the foreground. Just enough detail to feel old, and cool (literally).</td>', 'Very nice timing on the capture. I like the darkness in the foreground. Just enough detail to feel old, and cool (literally).', '2020-06-12 11:30:08.000000', NULL, 1),
(7666126, 1250165, 65234, '<td valign="top">I like your subject matter. Not sure what I think of all the grain. Although I suppose it''s appropriate for a picture of sand ;-)</td>', 'I like your subject matter. Not sure what I think of all the grain. Although I suppose it''s appropriate for a picture of sand ;-)', '2020-06-12 11:31:55.000000', NULL, 1),
