(7666190, 1250642, 94815, '<td valign="top">Amazing to see no people on the walkway! Must be recent but the B/W makes it look classic except for the modern Manhattan buildings.</td>', 'Amazing to see no people on the walkway! Must be recent but the B/W makes it look classic except for the modern Manhattan buildings.', '2020-06-13 13:31:31.000000', NULL, 1),
(7666192, 1250253, 94815, '<td valign="top">Evocative study in visual counterpoint for the subject. My top pick.</td>', 'Evocative study in visual counterpoint for the subject. My top pick.', '2020-06-13 13:48:26.000000', NULL, 1),
(7666193, 1250619, 94815, '<td valign="top">Good path. Pleasantly nostalgic.</td>', 'Good path. Pleasantly nostalgic.', '2020-06-13 13:50:51.000000', NULL, 1),
(7666286, 1250534, 114285, '<td valign="top">What a scene.</td>', 'What a scene.', '2020-06-15 06:01:48.000000', NULL, 1),
