(7666423, 1250581, 147314, '<td valign="top">I guess another one from Iceland. Beautiful image!</td>', 'I guess another one from Iceland. Beautiful image!', '2020-06-16 06:47:52.000000', NULL, 1),
(7666424, 1250690, 24511, '<td valign="top">Had this one at 4 score but second thorough look lived the stars and aurora borealis feeling.  Too green at fists glance as if a filter was used and ruined everything. Road prominent almost disguised in our face yet not so obvious. Biggest surprise for me bumping up to 8 doubling my initial glance score</td>', 'Had this one at 4 score but second thorough look lived the stars and aurora borealis feeling.  Too green at fists glance as if a filter was used and ruined everything. Road prominent almost disguised in our face yet not so obvious. Biggest surprise for me bumping up to 8 doubling my initial glance score', '2020-06-16 06:49:58.000000', NULL, 1),
(7666425, 1250427, 147314, '<td valign="top">I think this one is a bit ruined by the used editing technique. Gave it a 5, but could easily have been a 8 without the strong editing applied.</td>', 'I think this one is a bit ruined by the used editing technique. Gave it a 5, but could easily have been a 8 without the strong editing applied.', '2020-06-16 06:51:43.000000', NULL, 1),
(7666426, 1250508, 147314, '<td valign="top">Quite DMC, but I think the foreground could have been a bit more interesting (a bit more contrast and saturation or warmth)</td>', 'Quite DMC, but I think the foreground could have been a bit more interesting (a bit more contrast and saturation or warmth)', '2020-06-16 06:53:51.000000', NULL, 1),
